import { Component } from '@angular/core';

@Component({
  selector: 'app-about',
  templateUrl: './about.component.html',
  styleUrls: ['./about.component.scss']
})
export class AboutComponent { }
<section class="section about-page">
  <h2>About Divara Craft</h2>
  <p>Divara Craft is a boutique marketplace showcasing handcrafted art, decor, and accessories made with love by expert artisans. Our mission is to bring cultural heritage and creative craftsmanship into your everyday life.</p>
  <p>From elegant handmade bangles to unique home decor pieces, every item is made with quality materials and attention to detail. Shop with confidence and support artisan communities with every purchase.</p>
</section>
